// Look for the data that's being passed to the project cards
// Check if there's any global state or data we can inspect
return document.querySelectorAll('[class*="card"], [class*="Card"], [class*="project"], [class*="Project"]').length;

// Find the "Something went wrong" text and its surrounding context
const allElements = document.querySelectorAll('*');
let result = [];
for (const el of allElements) {
  if (el.textContent.includes('Something went wrong') && el.children.length < 3) {
    result.push({
      tag: el.tagName,
      className: el.className,
      innerHTML: el.innerHTML.substring(0, 500),
      parentClass: el.parentElement?.className,
      parentParentClass: el.parentElement?.parentElement?.className
    });
  }
}
return JSON.stringify(result);

// Find the "Something went wrong" element and examine its parent card
const allDivs = document.querySelectorAll('div');
for (const div of allDivs) {
  if (div.textContent === 'Something went wrong' && div.children.length === 0) {
    const card = div.parentElement;
    return JSON.stringify({
      errorText: div.textContent,
      errorStyle: div.getAttribute('style'),
      cardStyle: card?.getAttribute('style'),
      cardHTML: card?.innerHTML?.substring(0, 1000),
      siblingsBefore: div.previousElementSibling?.textContent,
      siblingsAfter: div.nextElementSibling?.textContent,
      // Check what data attribute or id is on the card
      cardDataset: card?.dataset,
      cardId: card?.id
    });
  }
}
return 'not found';

// Try to find the project data - look for React fiber or any data store
const root = document.getElementById('root');
const fiberKey = Object.keys(root).find(k => k.startsWith('__reactFiber'));
if (fiberKey) {
  // Walk the fiber tree to find the data
  let fiber = root[fiberKey];
  let stateNodes = [];
  function walkFiber(f, depth) {
    if (!f || depth > 20) return;
    if (f.memoizedProps && f.memoizedProps.projects) {
      stateNodes.push(JSON.stringify(f.memoizedProps.projects));
    }
    if (f.memoizedState && f.memoizedState.memoizedState) {
      // could be a hook state
    }
    walkFiber(f.child, depth + 1);
    walkFiber(f.sibling, depth + 1);
  }
  walkFiber(fiber, 0);
  return JSON.stringify(stateNodes);
}
return 'no fiber found';

// Try alternate react internal key
const root = document.getElementById('root');
const keys = Object.keys(root);
return JSON.stringify(keys);

const root = document.getElementById('root');
const containerKey = Object.keys(root).find(k => k.startsWith('__reactContainer'));
if (containerKey) {
  let fiber = root[containerKey];
  let results = [];
  function walkFiber(f, depth) {
    if (!f || depth > 30) return;
    // Look for project data in props
    if (f.memoizedProps) {
      const props = f.memoizedProps;
      if (props.project || props.stats || props.name === 'Data Pipeline') {
        results.push({
          type: f.type?.name || f.type || 'unknown',
          props: JSON.stringify(props).substring(0, 500)
        });
      }
    }
    walkFiber(f.child, depth + 1);
    walkFiber(f.sibling, depth + 1);
  }
  walkFiber(fiber, 0);
  return JSON.stringify(results);
}
return 'no container';
